param([string]$Source="source-private/SEIF-master-v0.1.docx")
$ErrorActionPreference="Stop";$repo=Split-Path -Parent $PSScriptRoot;$sourcePath=Join-Path $repo $Source
if(-not(Test-Path -LiteralPath $sourcePath -PathType Leaf)){throw"SOURCE NOT FOUND"}
Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($sourcePath)
try{$entry=$zip.GetEntry("word/document.xml");$reader=[IO.StreamReader]::new($entry.Open());try{[xml]$document=$reader.ReadToEnd()}finally{$reader.Dispose()}}finally{$zip.Dispose()}
$ns=[Xml.XmlNamespaceManager]::new($document.NameTable);$ns.AddNamespace("w","http://schemas.openxmlformats.org/wordprocessingml/2006/main");$body=$document.SelectSingleNode("//w:body",$ns)
function Text-Of($node){return (($node.SelectNodes(".//w:t",$ns)|ForEach-Object{$_.InnerText})-join"").Trim()}
function Max-Size($p){$s=@($p.SelectNodes(".//w:rPr/w:sz",$ns)|ForEach-Object{[int]$_.GetAttribute("val",$ns.LookupNamespace("w"))});if(!$s.Count){return 0};return ($s|Measure-Object -Maximum).Maximum}
function Slugify([string]$v){$n=$v.Normalize([Text.NormalizationForm]::FormD);$c=$n.ToCharArray()|Where-Object{[Globalization.CharUnicodeInfo]::GetUnicodeCategory($_)-ne[Globalization.UnicodeCategory]::NonSpacingMark};return ((-join$c).ToLowerInvariant()-replace"[^a-z0-9]+","-").Trim("-")}
function Ref([string]$locator){return [ordered]@{title="13. Decision & Prioritization Model";locator=$locator}}
function CV([string]$id,[string]$subject){return [ordered]@{id=$id;subject=$subject;status="CLIENT VALIDATION REQUIRED"}}
function Completeness([string[]]$complete,[string[]]$partial,[string[]]$missing){$v=[ordered]@{};foreach($k in $complete){$v[$k]="SOURCE COMPLETE"};foreach($k in $partial){$v[$k]="SOURCE PARTIAL"};foreach($k in $missing){$v[$k]="SOURCE MISSING"};return $v}
function Section-Class([string]$title){if($title-match'(?i)Maturity|North Star'){return "hypothesis"};if($title-match'(?i)assessment|AS-IS|Cambio esperado|Diagnóstico final'){return "mixed"};return "recommendation"}
function Validations-For([string]$title){$r=@();if($title-match'(?i)Decision Rights|Rol de liderazgo'){$r+=,(CV "CL-05" "Authority, accountability y participación en decisiones")};if($title-match'(?i)WIP|Active Outcomes'){$r+=,(CV "CL-09" "Límites numéricos de WIP y Outcomes activos")};if($title-match'(?i)Balance de inversión|deuda técnica'){$r+=,(CV "CL-12" "Política de capacidad y deuda técnica")};if($title-match'(?i)Decision Cadence|Opportunity Review|Governance'){$r+=,(CV "CL-11" "Cadencias de decisión, participantes y triggers")};if($title-match'(?i)Métricas|Decision Lead Time|Focus Ratio'){$r+=,(CV "CL-07" "Definiciones operacionales, baseline, target y ownership de métricas")};if($title-match'(?i)Integración con Jira|Estados recomendados'){$r+=,(CV "CL-10" "Arquitectura futura de tooling para DECIDE")};if($title-match'(?i)North Star'){$r+=,(CV "CL-06" "North Star candidate como señal de priorización")};if($title-match'(?i)Growth'){$r+=,(CV "CL-13" "Ownership de Growth y Expansion")};return $r}

$chapter=[ordered]@{sections=@();start=$null;end=$null};$current=0;$expected=1;$pi=0;$ti=0;$section=$null;$pending=@();$pendingStart=$null;$pendingEnd=$null
function Flush-List{if($null-ne$script:section-and$script:pending.Count){$script:section.blocks+=[ordered]@{type="list";items=@($script:pending);source=(Ref "P$script:pendingStart–P$script:pendingEnd")}};$script:pending=@();$script:pendingStart=$null;$script:pendingEnd=$null}
foreach($node in $body.ChildNodes){if($node.LocalName-eq"p"){$pi++;$text=Text-Of $node;if($expected-le14-and$text-match("^"+$expected+"\.\s+")-and(Max-Size $node)-ge36){Flush-List;$current=$expected;$expected++;if($current-eq13){$chapter.start="P$pi";$section=$null;continue};if($current-eq14){$chapter.end="P$($pi-1)";break}};if($current-ne13){continue};$chapter.end="P$pi";if(!$text){Flush-List;continue};if($text-match'^13\.\d+\s+'){Flush-List;$title=($text-replace'^13\.\d+\s+','').Trim();$section=[ordered]@{id=(Slugify $title);title=$title;contentClass=(Section-Class $title);blocks=@();evidence=@();sources=@((Ref "P$pi"))};$v=Validations-For $title;if($v.Count){$section.clientValidations=@($v)};$chapter.sections+=$section;continue};if($null-eq$section){continue};$isList=$null-ne$node.SelectSingleNode("./w:pPr/w:numPr",$ns);if($isList){if(!$pending.Count){$pendingStart=$pi};$pendingEnd=$pi;$pending+=$text}else{Flush-List;$section.blocks+=[ordered]@{type="paragraph";text=$text;source=(Ref "P$pi")}}}elseif($node.LocalName-eq"tbl"){$ti++;if($current-ne13){continue};Flush-List;$rows=@();foreach($row in $node.SelectNodes("./w:tr",$ns)){$rows+=,@($row.SelectNodes("./w:tc",$ns)|ForEach-Object{Text-Of $_})};if($rows.Count-and$null-ne$section){$headers=@($rows[0]);$data=if($rows.Count-gt1){@($rows[1..($rows.Count-1)])}else{@()};$kind=if(($headers-join" ")-match'(?i)Dimensión|Decisión|Nivel|Opportunity'){"comparison"}elseif(($headers-join" ")-match'(?i)Métrica'){"scorecard"}else{"simple"};$section.blocks+=[ordered]@{type="table";table=[ordered]@{id=("source-table-{0:D3}"-f$ti);caption=$section.title;kind=$kind;headers=$headers;rows=$data;source=(Ref "T$ti")}}}}};Flush-List

$semantic=@(
 [ordered]@{term="ASSESSMENT";definition="Diagnóstico que evidencia criterios distribuidos y falta de lógica común trazable; no es la priorización misma.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4513–P4525")},
 [ordered]@{term="PRIORITIZATION";definition="Decisión razonada sobre qué problema u Opportunity merece capacidad ahora, considerando Outcome, Evidence, Reach, Value y Feasibility.";sourceStatus="SOURCE COMPLETE";source=(Ref "P4527–P4577; P5261–P5287")},
 [ordered]@{term="RANKING";definition="Ordenar una lista no completa la priorización; la fuente rechaza que el número más alto produzca automáticamente prioridad.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4731–P4742; P4886–P4898")},
 [ordered]@{term="SEQUENCING";definition="NOW, NEXT y LATER organizan horizontes sin convertirlos en promesas detalladas.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4911–P4919")},
