 [ordered]@{term="COMMITMENT";definition="Inicio posterior a la prioridad cuando existe capacidad; una Opportunity priorizada puede permanecer Not Started.";sourceStatus="SOURCE COMPLETE";source=(Ref "P4886–P4898; P5248–P5254")},
 [ordered]@{term="CAPACITY ALLOCATION";definition="Visibilidad y balance de capacidad comprometida por Outcome y Run/Grow/Transform; no se fijan porcentajes sin baseline.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4766–P4788")},
 [ordered]@{term="FUNDING / INVESTMENT";definition="La fuente habla de decisión de inversión y compromiso financiero significativo, pero no define un mecanismo de funding separado.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4513–P4514; P4755–P4763")},
 [ordered]@{term="BACKLOG ORDERING";definition="El backlog no es la unidad de decisión; guardar u ordenar oportunidades sin decisión explícita aparece como anti-patrón.";sourceStatus="SOURCE PARTIAL";source=(Ref "P4540–P4558; P4981–P4996")}
)
$decideComplete=Completeness @("WHAT","WHY","INPUT","OUTPUT","DECISION","DECISION CRITERIA","TRADE-OFF","CAPACITY CONSTRAINT","REVISIT CONDITION","DECISION RECORD") @("HOW","WHO","WHEN","ARTIFACT","METRIC","EXAMPLE") @("TOOL")
function DC([string]$id,[string]$kind,[string]$title,[string]$what,[string]$why,[string]$locator,[string[]]$criteria,[string[]]$outputs,[string]$trigger="",[string[]]$inputs=@(),[string[]]$participants=@(),[string]$owner="",[string]$artifact="",[string]$metric="",[string]$cadence=""){
 $value=[ordered]@{id=$id;kind=$kind;title=$title;what=$what;why=$why;trigger=$trigger;inputs=$inputs;criteria=$criteria;participants=$participants;decisionOwner=$owner;outputs=$outputs;metric=$metric;cadence=$cadence;sourceLocators=@((Ref $locator));contentClass="recommendation";completeness=$decideComplete}
 if($artifact){$value.artifacts=[string[]]@($artifact)}
 return $value
}
